entries[311424] = { ["name"] = "Codex of the Still Mind", ["text"] = "2 sec cast\nTools: Virtuoso Inking Set\nReagents:\nLuminous Ink (7), Umbral Ink (7), Tranquil Ink , Dark Parchment (75)\nVendor:\nAdjutant Mikaros\nZone:\nOribos\nThe Ascended - Friendly\nCost:\n8\n\nVendor:\nAdjutant Nikos\nZone:\nBastion\nThe Ascended - Friendly\nCost:\n8\n\nCodex of the Still Mind\nUse: Set out a codex, allowing nearby players to adjust their talents.\n51\n\"Created by players with the Inscription skill. Can be bought and sold on the auction house.\"" }
